import { products, intent, installOwnedCartHooks, selectAndAdd, assertCart, assertEmpty,
  changeCartQuantity, removeCartLine, recoverToSelectableProduct } from '../../support/cart';

describe('Owned guest-cart visible quantity, removal and recovery', () => {
  const registerOwned = installOwnedCartHooks();
  it('CART-E01 — increasing then decreasing one line preserves the other product', () => {
    cy.viewport(1366, 900);
    const target = intent(products.blackFriday, products.blackFriday.default, 2);
    const other = intent(products.simple, products.simple.default, 1);
    selectAndAdd(target, registerOwned); assertCart([target]);
    selectAndAdd(other, registerOwned); assertCart([target, other]);
    changeCartQuantity(target, 'increase', [target, other]);
    // The next intended value is read when this queued operation starts, after
    // the previous correlated quote updates the independently specified intent.
    cy.then(() => changeCartQuantity(target, 'decrease', [target, other]));
  });
  it('CART-E02 — removing one product preserves the entire remaining configuration', () => {
    cy.viewport(1366, 900);
    const target = intent(products.blackFriday, products.blackFriday.default, 2);
    const other = intent(products.simple, products.simple.default, 1);
    selectAndAdd(target, registerOwned); assertCart([target]);
    selectAndAdd(other, registerOwned); assertCart([target, other]);
    removeCartLine(target); assertCart([other]);
  });
  it('CART-E03 — removing the final item restores empty-cart product recovery', () => {
    cy.viewport(1366, 900);
    const target = intent(products.simple, products.simple.default, 1);
    selectAndAdd(target, registerOwned); assertCart([target]);
    removeCartLine(target); assertEmpty();
    recoverToSelectableProduct(products.simple);
  });
  it('CART-E04 — narrow visible steppers change only the intended package quantity', () => {
    cy.viewport(390, 844);
    const target = intent(products.blackFriday, products.blackFriday.alternate, 2);
    selectAndAdd(target, registerOwned, 'narrow'); assertCart([target]);
    changeCartQuantity(target, 'increase', [target]);
    cy.then(() => changeCartQuantity(target, 'decrease', [target]));
  });
});
